def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = {}
    for k, v in opponents_status.items():
        if v.get('alive'):
            alive[k] = v

    if not alive:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, 63.0))
        return float(min(budget, 18.0))

    prev_bids = []
    cindy_bid = None
    urgent_opp = False
    rich_threat = 0.0

    for oid, opp in alive.items():
        obudget = opp.get('budget', 0.0)
        ohp = opp.get('hp', 0)
        onw = opp.get('no_water_days', 0)
        if obudget > rich_threat:
            rich_threat = obudget
        if ohp <= 2 or onw >= 2:
            urgent_opp = True
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if oid == 'Cindy':
                cindy_bid = float(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    units = supply / WATER_REQ
    scarce = units < 2.0
    very_scarce = units < 1.3

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 1
    if scarce:
        danger += 1
    if very_scarce:
        danger += 1
    if urgent_opp:
        danger += 1

    bid = 0.0

    if danger >= 5:
        anchor = max(66.0, highest_prev + 4.0, (cindy_bid + 3.0) if cindy_bid is not None else 0.0)
        bid = anchor
    elif danger >= 3:
        if scarce:
            anchor = max(48.0, avg_prev + 2.0, (cindy_bid - 8.0) if cindy_bid is not None else 0.0)
            bid = anchor
        else:
            bid = max(28.0, avg_prev * 0.45)
    else:
        if scarce:
            bid = max(22.0, avg_prev * 0.35)
        else:
            bid = 12.0

    if cindy_bid is not None:
        if hp > 4 and no_water == 0 and not very_scarce:
            bid = min(bid, max(12.0, cindy_bid * 0.22))
        elif danger >= 3:
            bid = max(bid, cindy_bid + 1.25)

    if budget < 90:
        if danger <= 2:
            bid = min(bid, 18.0)
        elif danger == 3:
            bid = min(bid, 42.0)

    if day >= 8:
        if hp > 4 and no_water == 0:
            bid *= 0.9
        else:
            bid *= 1.05

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate Cindy as the most aggressive based on yesterday bid
    aggressor_bid = 0.0
    if prev_bids:
        aggressor_bid = max(prev_bids)

    # Convert aggressor pressure into a target bid band
    # If someone was bidding very high yesterday, we keep our bid competitive but not maximal.
    if aggressor_bid >= DAILY_SALARY * 1.5:
        # Cindy-like pressure: bid slightly above a conservative cut-off, but cap by what we can afford.
        base = DAILY_SALARY * 0.95
    elif aggressor_bid >= DAILY_SALARY * 1.1:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.58

    # Adjust for current supply: with higher supply, we can win with lower bid.
    # supply in [15,25]
    supply_frac = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    # When supply is high, reduce bid slightly; when low, increase slightly.
    supply_adjust = 1.0 - 0.12 * supply_frac + 0.08 * (1.0 - supply_frac)

    # Urgency based on hp / no_water_days
    hp = int(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])

    urgency = 1.0
    if hp <= 2:
        urgency = 1.25
    elif hp <= 4:
        urgency = 1.12

    if no_water_days >= 2:
        urgency += 0.10
    if no_water_days >= 3:
        urgency += 0.15

    target = base * supply_adjust * urgency

    # If yesterday aggressor bid was extremely high, try to beat a fraction of it.
    if aggressor_bid > 0:
        target = max(target, aggressor_bid * 0.62)

    # Ensure we never overbid beyond budget; also keep a reserve so we can respond later.
    budget = float(my_status['budget'])
    reserve = DAILY_SALARY * 0.15
    max_affordable = max(0.0, budget - reserve)

    # Final clamp
    bid = min(max_affordable, target)

    # If our budget is tiny, still bid something minimal to avoid total loss.
    if bid <= 0.0:
        return min(budget, DAILY_SALARY * 0.05)

    return bid

def get_bid(day_context, my_status, opponents_status):
