    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 50.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0
    max_prev = max(yesterday_bids) if yesterday_bids else 80.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max_prev + 5.0)
    elif supply < 18:
        bid = min(my_status['budget'], max(avg_bid * 1.1, 85.0))
    else:
        bid = min(my_status['budget'], avg_bid * 0.95)

    return float(max(0.0, bid))

